<?php
/**
 * STEP 6 — Parent/Guardian Documents. Audit-only endpoint.
 *
 * The document itself (Conference Notice / Referral Letter) is rendered
 * entirely client-side (see printDocument() in admin.js) from data the
 * entry point already loaded — nothing here stores or returns document
 * content. This endpoint's only job is the server-side role check (so a
 * document can never actually be generated by an unauthorized role, even
 * though rendering happens in the browser) and the audit_trail entry.
 *
 * Deliberately does NOT log the summary/purpose text itself — only the
 * document type, student, and source record — so a staff member's
 * carefully-worded parent-facing summary isn't duplicated into a second
 * place beyond their control.
 */
require_once "../config/session_init.php";
session_start();
header("Content-Type: application/json");
include "../config/database.php";

if (!isset($_SESSION['user_id'])) {
    echo json_encode(["success" => false, "message" => "Unauthorized"]);
    exit();
}

require_once "../config/csrf.php";
csrf_verify();
require_once "../config/session_guard.php";
enforce_session_timeout();
require_once "../config/audit.php";

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    echo json_encode(["success" => false, "message" => "Only POST is supported."]);
    exit();
}

$role = $_SESSION['role'] ?? '';
$data = json_decode(file_get_contents("php://input"), true);

$documentType = trim($data['document_type'] ?? ''); // 'conference' | 'referral'
$studentId    = intval($data['student_id']  ?? 0);
$sourceType   = trim($data['source_type']   ?? '');  // 'student' | 'referral' | 'counseling'
$sourceId     = intval($data['source_id']   ?? 0);

if (!in_array($documentType, ['conference', 'referral'], true) || !$studentId) {
    echo json_encode(["success" => false, "message" => "Invalid document request."]);
    exit();
}

// Role boundary — mirrors the module that already owns the source data:
// Referral Letter reads from `referrals` (Clinic-owned, Step 1) so it
// follows the exact same RBAC as api/referrals.php. Conference Notice is
// Guidance-flavored (behavioral/counseling/disciplinary concerns) so it
// follows api/behavioral.php / api/counseling.php's RBAC.
if ($documentType === 'referral' && !in_array($role, ['Administrator', 'Clinic Staff'], true)) {
    http_response_code(403);
    echo json_encode(["success" => false, "message" => "Forbidden"]);
    exit();
}
if ($documentType === 'conference' && !in_array($role, ['Administrator', 'Guidance Staff'], true)) {
    http_response_code(403);
    echo json_encode(["success" => false, "message" => "Forbidden"]);
    exit();
}

// Confirm the student actually exists (never trust student_id from the
// browser) — this also naturally rejects a stale/deleted student.
$stmt = $conn->prepare("SELECT id FROM students WHERE id = ?");
$stmt->bind_param("i", $studentId);
$stmt->execute();
if (!$stmt->get_result()->fetch_assoc()) {
    echo json_encode(["success" => false, "message" => "Student not found."]);
    exit();
}

// If a source record was given (referral/counseling), confirm it's real
// and actually belongs to this student — prevents generating a document
// that cites a mismatched or nonexistent record.
if ($sourceId && in_array($sourceType, ['referral', 'counseling'], true)) {
    $table = $sourceType === 'referral' ? 'referrals' : 'counseling_sessions';
    $stmt = $conn->prepare("SELECT id FROM {$table} WHERE id = ? AND student_id = ?");
    $stmt->bind_param("ii", $sourceId, $studentId);
    $stmt->execute();
    if (!$stmt->get_result()->fetch_assoc()) {
        echo json_encode(["success" => false, "message" => "Source record not found for this student."]);
        exit();
    }
}

$module = $documentType === 'referral' ? 'Clinic' : 'Guidance';
$label  = $documentType === 'referral' ? 'Referral Letter' : 'Parent/Guardian Conference Notice';

log_audit($conn, $_SESSION['user_id'], $module, 'Document Generated', $studentId,
    "{$label} generated for student #{$studentId}" . ($sourceId ? " (from {$sourceType} #{$sourceId})" : ""));

echo json_encode(["success" => true]);
exit();
